-- ES/DE/FR translations for the rest of Malaysia's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (MyInvois)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las reglas de validación de MyInvois, los umbrales de fase y las disposiciones sobre sanciones siguen evolucionando — confirme los requisitos actuales directamente con la LHDN antes de construir una integración.', 'La implementación de Malasia funciona de arriba hacia abajo por tramo de facturación, con un periodo de relajación que se extiende mucho más allá de la fecha formal de inicio de cada tramo.', 'Malasia admite genuinamente dos serializaciones de la misma estructura UBL 2.1 subyacente — elija la que mejor se adapte a su sistema, no un formato único fijo.', 'MyInvois es una auténtica plataforma de compensación: la LHDN valida en tiempo real y asigna identificadores antes de que una factura tenga fuerza legal.', 'Obtener credenciales de API es un proceso genuino de verificación de identidad de varios pasos, no un registro de autoservicio.', 'El incumplimiento se remite al marco general de la Ley del Impuesto sobre la Renta de Malasia en lugar de a un régimen de sanciones específico de facturación electrónica independiente.' FROM countries WHERE name_en = 'Malaysia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (MyInvois)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Validierungsregeln von MyInvois, Phasenschwellen und Sanktionsbestimmungen entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der LHDN, bevor Sie eine Integration aufbauen.', 'Malaysias Einführung erfolgt von oben nach unten nach Umsatzstufe, mit einer Lockerungsphase, die weit über das formale Startdatum jeder Stufe hinausreicht.', 'Malaysia unterstützt genuin zwei Serialisierungen derselben zugrunde liegenden UBL-2.1-Struktur — wählen Sie, was am besten zu Ihrem Stack passt, nicht ein festes einheitliches Format.', 'MyInvois ist eine echte Clearing-Plattform: Die LHDN validiert in Echtzeit und weist Kennungen zu, bevor eine Rechnung Rechtskraft erlangt.', 'Die Beschaffung von API-Zugangsdaten ist ein echter mehrstufiger Identitätsprüfungsprozess, keine Selbstbedienungsregistrierung.', 'Nichteinhaltung wird in Malaysias allgemeinen Rahmen des Einkommensteuergesetzes eingeordnet, statt in einen eigenständigen E-Invoicing-Sanktionskatalog.' FROM countries WHERE name_en = 'Malaysia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (MyInvois)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règles de validation de MyInvois, les seuils de phase et les dispositions relatives aux sanctions continuent d''évoluer — confirmez les exigences actuelles directement auprès de la LHDN avant de construire une intégration.', 'Le déploiement de la Malaisie fonctionne du haut vers le bas par tranche de chiffre d''affaires, avec une période d''assouplissement s''étendant bien au-delà de la date de démarrage formelle de chaque tranche.', 'La Malaisie prend véritablement en charge deux sérialisations de la même structure UBL 2.1 sous-jacente — choisissez celle qui convient le mieux à votre pile technique, pas un format unique fixe.', 'MyInvois est une véritable plateforme de contrôle : la LHDN valide en temps réel et attribue des identifiants avant qu''une facture n''ait force légale.', 'L''obtention d''identifiants API est un véritable processus de vérification d''identité en plusieurs étapes, pas une inscription en libre-service.', 'La non-conformité se rattache au cadre général de la loi malaisienne sur l''impôt sur le revenu plutôt qu''à un barème de sanctions autonome propre à la facturation électronique.' FROM countries WHERE name_en = 'Malaysia';

