INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato', '[["Estructura de datos", "UBL 2.1 (Universal Business Language)"], ["Serializaciones aceptadas", "XML o JSON"], ["Certificado digital", "Obligatorio, emitido por una Autoridad de Certificación malasia reconocida"]]', 'Tanto XML como JSON transportan el mismo modelo de datos UBL 2.1 — elija según lo que se integre de forma más limpia con su ERP actual, no por preferencia de cumplimiento.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format', '[["Datenstruktur", "UBL 2.1 (Universal Business Language)"], ["Akzeptierte Serialisierungen", "XML oder JSON"], ["Digitales Zertifikat", "Verpflichtend, ausgestellt von einer anerkannten malaysischen Zertifizierungsstelle"]]', 'Sowohl XML als auch JSON transportieren dasselbe UBL-2.1-Datenmodell — wählen Sie basierend darauf, was sich sauberer in Ihr bestehendes ERP integrieren lässt, nicht nach Compliance-Präferenz.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format', '[["Structure de données", "UBL 2.1 (Universal Business Language)"], ["Sérialisations acceptées", "XML ou JSON"], ["Certificat numérique", "Obligatoire, délivré par une autorité de certification malaisienne reconnue"]]', 'XML et JSON véhiculent tous deux le même modèle de données UBL 2.1 — choisissez selon ce qui s''intègre le mieux à votre ERP existant, pas par préférence de conformité.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Format';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Campos de datos obligatorios', '[["Número de campos", "55 campos de datos específicos"], ["Cubre", "Datos del vendedor/comprador, artículos de la transacción, cantidades, precios, impuestos, totales, información de pago"], ["Campos de referencia", "TIN, código MSIC, clasificación fiscal"]]', 'Las fallas de validación en la LHDN se rechazan de forma cerrada — el documento se rechaza directamente en lugar de aceptarse con una advertencia, por lo que acertar con estos 55 campos desde el principio realmente importa.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Mandatory data fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtdatenfelder', '[["Feldanzahl", "55 spezifische Datenfelder"], ["Umfasst", "Verkäufer-/Käuferdaten, Transaktionspositionen, Mengen, Preise, Steuern, Summen, Zahlungsinformationen"], ["Referenzfelder", "TIN, MSIC-Code, Steuerklassifizierung"]]', 'Validierungsfehler bei der LHDN schlagen fehlgeschlossen zu — das Dokument wird direkt abgelehnt statt mit einer Warnung akzeptiert, weshalb es wirklich darauf ankommt, diese 55 Felder gleich beim ersten Mal richtig zu haben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Mandatory data fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Champs de données obligatoires', '[["Nombre de champs", "55 champs de données spécifiques"], ["Couvre", "Détails vendeur/acheteur, articles de la transaction, quantités, prix, taxes, totaux, informations de paiement"], ["Champs de référence", "TIN, code MSIC, classification fiscale"]]', 'Les échecs de validation auprès de la LHDN se soldent par un rejet fermé — le document est rejeté d''emblée plutôt qu''accepté avec un avertissement, ce qui rend crucial d''obtenir ces 55 champs correctement dès la première fois.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Mandatory data fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Tipos de documento (8 en total)', '[["Tipos estándar", "Factura, nota de crédito, nota de débito, nota de reembolso"], ["Variantes autofacturadas", "Cuatro equivalentes, para escenarios de autofacturación"]]', 'Las facturas autofacturadas se tratan como un conjunto de tipos de documento genuinamente distinto, no solo como una marca sobre el tipo de factura estándar — planifique su integración en consecuencia si utiliza la autofacturación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Document types (8 total)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Dokumenttypen (8 insgesamt)', '[["Standardtypen", "Rechnung, Gutschrift, Lastschrift, Rückerstattungsbeleg"], ["Selbstfakturierungs-Varianten", "Vier Entsprechungen, für Selbstfakturierungsszenarien"]]', 'Selbstfakturierte Rechnungen werden als genuin eigenständiger Dokumenttypensatz behandelt, nicht nur als Kennzeichen auf dem Standardrechnungstyp — planen Sie Ihre Integration entsprechend, wenn Sie Selbstfakturierung nutzen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Document types (8 total)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Types de documents (8 au total)', '[["Types standard", "Facture, note de crédit, note de débit, note de remboursement"], ["Variantes autofacturées", "Quatre équivalents, pour les scénarios d''autofacturation"]]', 'Les factures autofacturées sont traitées comme un ensemble de types de documents véritablement distinct, pas seulement comme un indicateur sur le type de facture standard — planifiez votre intégration en conséquence si vous utilisez l''autofacturation.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Document types (8 total)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Peppol como vía separada', '[["Gestionado por", "MDEC (Malaysia Digital Economy Corporation)"], ["Se usa para", "Intercambio de facturas transfronterizo y B2G"], ["Diferencia de formato", "MyInvois suele usar UBL 2.1 JSON; Peppol usa UBL 2.1 XML con PINT"]]', 'Una empresa puede usar, y a menudo usa, ambas vías simultáneamente — MyInvois para el cumplimiento nacional, Peppol para la contratación pública o clientes internacionales — pero son protocolos genuinamente diferentes que requieren un tratamiento separado.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Peppol as a separate track';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Peppol als separater Weg', '[["Verwaltet von", "MDEC (Malaysia Digital Economy Corporation)"], ["Verwendet für", "Grenzüberschreitenden und B2G-Rechnungsaustausch"], ["Formatunterschied", "MyInvois nutzt typischerweise UBL 2.1 JSON; Peppol nutzt UBL 2.1 XML mit PINT"]]', 'Ein Unternehmen kann und nutzt oft beide Wege gleichzeitig — MyInvois für die inländische Compliance, Peppol für öffentliche Beschaffung oder internationale Kunden — doch es handelt sich um genuin unterschiedliche Protokolle, die getrennt behandelt werden müssen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Peppol as a separate track';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Peppol comme voie distincte', '[["Géré par", "MDEC (Malaysia Digital Economy Corporation)"], ["Utilisé pour", "L''échange de factures transfrontalier et B2G"], ["Différence de format", "MyInvois utilise généralement UBL 2.1 JSON ; Peppol utilise UBL 2.1 XML avec PINT"]]', 'Une entreprise peut utiliser, et utilise souvent, les deux voies simultanément — MyInvois pour la conformité domestique, Peppol pour les marchés publics ou les clients internationaux — mais ce sont des protocoles véritablement différents nécessitant un traitement distinct.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'file_format' AND dct.title = 'Peppol as a separate track';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Mecánica de la API', '[["Autenticación", "OAuth 2.0, ámbito \"InvoicingAPI\""], ["Identidad", "TIN del contribuyente + NRIC/BRN"], ["Endpoint", "POST a /api/v1.0/documents/submit"], ["Credenciales", "Específicas del entorno — sandbox y producción son independientes"]]', 'No reutilice las credenciales de sandbox en producción ni viceversa — la LHDN emite pares distintos de ID/secreto de cliente para cada entorno a través del portal de desarrolladores de MyInvois.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'API mechanics';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'API-Mechanik', '[["Authentifizierung", "OAuth 2.0, Scope \"InvoicingAPI\""], ["Identität", "Steuerzahler-TIN + NRIC/BRN"], ["Endpunkt", "POST an /api/v1.0/documents/submit"], ["Zugangsdaten", "Umgebungsspezifisch — Sandbox und Produktion sind getrennt"]]', 'Verwenden Sie Sandbox-Zugangsdaten nicht in der Produktion oder umgekehrt — die LHDN vergibt über das MyInvois-Entwicklerportal für jede Umgebung eigene Client-ID-/Secret-Paare.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'API mechanics';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Mécanique de l''API', '[["Authentification", "OAuth 2.0, portée « InvoicingAPI »"], ["Identité", "TIN du contribuable + NRIC/BRN"], ["Point de terminaison", "POST vers /api/v1.0/documents/submit"], ["Identifiants", "Spécifiques à l''environnement — le bac à sable et la production sont distincts"]]', 'Ne réutilisez pas les identifiants du bac à sable en production ni l''inverse — la LHDN délivre des paires d''identifiant/secret client distinctes pour chaque environnement via le portail développeur MyInvois.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'API mechanics';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La ventana de 72 horas', '[["Solicitud de rechazo del comprador", "En un plazo de 72 horas desde la validación"], ["Cancelación por el emisor", "En un plazo de 72 horas desde la aprobación"], ["Tras la ventana", "Debe emitirse en su lugar una nota de crédito/débito"]]', 'Intentar cancelar fuera de esta ventana devuelve un error "OperationPeriodOver" — planifique su flujo de corrección en torno a las notas de crédito/débito como vía de respaldo, no la cancelación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'The 72-hour window';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Das 72-Stunden-Fenster', '[["Ablehnungsanfrage des Käufers", "Innerhalb von 72 Stunden nach Validierung"], ["Stornierung durch den Aussteller", "Innerhalb von 72 Stunden nach Genehmigung"], ["Nach dem Fenster", "Es muss stattdessen eine Gutschrift/Lastschrift ausgestellt werden"]]', 'Der Versuch, außerhalb dieses Fensters zu stornieren, liefert einen "OperationPeriodOver"-Fehler — planen Sie Ihren Korrekturworkflow rund um Gutschriften/Lastschriften als Rückfalllösung, nicht die Stornierung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'The 72-hour window';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La fenêtre de 72 heures', '[["Demande de rejet de l''acheteur", "Dans les 72 heures suivant la validation"], ["Annulation par l''émetteur", "Dans les 72 heures suivant l''approbation"], ["Après la fenêtre", "Une note de crédit/débit doit être émise à la place"]]', 'Tenter d''annuler en dehors de cette fenêtre renvoie une erreur « OperationPeriodOver » — planifiez votre flux de correction autour des notes de crédit/débit comme solution de repli, pas l''annulation.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'scope_transmission' AND dct.title = 'The 72-hour window';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Responsabilidad conforme a la Sección 120', NULL, NULL, 'El incumplimiento del mandato de facturación electrónica se cita comúnmente como una exposición a sanciones bajo la Sección 120 de la Ley del Impuesto sobre la Renta — confirme las cifras actuales con la LHDN o un asesor fiscal malasio, ya que disposiciones generales sobre infracciones fiscales como esta se revisan periódicamente.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Section 120 liability';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Haftung nach Section 120', NULL, NULL, 'Die Nichteinhaltung der E-Invoicing-Vorgabe wird häufig als Aussetzung gegenüber Sanktionen nach Section 120 des Einkommensteuergesetzes genannt — bestätigen Sie die aktuellen Zahlen bei der LHDN oder einem malaysischen Steuerberater, da allgemeine Steuervergehensbestimmungen wie diese regelmäßig überarbeitet werden.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Section 120 liability';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Responsabilité au titre de la Section 120', NULL, NULL, 'Le non-respect de l''obligation de facturation électronique est fréquemment cité comme exposant les entreprises à des sanctions au titre de la Section 120 de la loi sur l''impôt sur le revenu — confirmez les chiffres actuels auprès de la LHDN ou d''un conseiller fiscal malaisien, ces dispositions générales relatives aux infractions fiscales étant révisées périodiquement.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '⚖️ Section 120 liability';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Facturas electrónicas consolidadas para retail/B2C', NULL, NULL, 'Los escenarios de retail y otros de alto volumen B2C cuentan con un mecanismo de factura electrónica consolidada para aliviar la carga de la facturación individual — vale la pena investigarlo si su empresa gestiona altos volúmenes de transacciones con consumidores individuales.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🧾 Consolidated e-invoices for retail/B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Konsolidierte E-Rechnungen für Einzelhandel/B2C', NULL, NULL, 'Für Einzelhandel und andere B2C-Szenarien mit hohem Volumen gibt es einen Mechanismus für konsolidierte E-Rechnungen, um die Last der Einzelfakturierung zu verringern — lohnt sich zu prüfen, wenn Ihr Unternehmen hohe Transaktionsvolumen mit Einzelverbrauchern abwickelt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🧾 Consolidated e-invoices for retail/B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Factures électroniques consolidées pour le commerce de détail/B2C', NULL, NULL, 'Le commerce de détail et d''autres scénarios B2C à fort volume disposent d''un mécanisme de facture électronique consolidée pour alléger la charge de la facturation individuelle — à examiner si votre entreprise traite des volumes de transactions élevés avec des consommateurs individuels.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🧾 Consolidated e-invoices for retail/B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📅 Errores comunes de implementación', NULL, NULL, 'Los TIN ausentes o con formato incorrecto, el uso de formatos no compatibles, no gestionar los rechazos con prontitud y no archivar las respuestas de validación junto con la factura original son los errores de implementación inicial más citados con frecuencia.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '📅 Common implementation mistakes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📅 Häufige Umsetzungsfehler', NULL, NULL, 'Fehlende oder falsch formatierte TINs, die Verwendung nicht unterstützter Formate, das nicht rechtzeitige Bearbeiten von Ablehnungen und die Vernachlässigung der Archivierung von Validierungsantworten zusammen mit der Originalrechnung sind die am häufigsten genannten Erstumsetzungsfehler.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '📅 Common implementation mistakes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📅 Erreurs de mise en œuvre courantes', NULL, NULL, 'Des TIN manquants ou mal formatés, l''utilisation de formats non pris en charge, le fait de ne pas traiter rapidement les rejets et la négligence d''archiver les réponses de validation avec la facture d''origine sont les erreurs de première mise en œuvre les plus fréquemment citées.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '📅 Common implementation mistakes';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔮 Mirando hacia 2027-2030', NULL, NULL, 'La hoja de ruta declarada de la LHDN sigue evolucionando más allá de las fases actuales — siga la orientación oficial ante cualquier nueva ampliación del alcance o requisitos de nuevos tipos de documentos a medida que el mandato madura.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🔮 Looking to 2027–2030';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔮 Blick auf 2027-2030', NULL, NULL, 'Der erklärte Fahrplan der LHDN entwickelt sich über die aktuellen Phasen hinaus weiter — verfolgen Sie offizielle Leitlinien zu jeder weiteren Ausweitung des Anwendungsbereichs oder neuen Dokumenttypanforderungen, während die Vorgabe reift.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🔮 Looking to 2027–2030';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔮 Perspectives 2027-2030', NULL, NULL, 'La feuille de route déclarée de la LHDN continue d''évoluer au-delà des phases actuelles — suivez les directives officielles pour toute nouvelle extension du champ d''application ou exigence de nouveau type de document à mesure que l''obligation mûrit.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Malaysia' AND dc.section = 'penalties_related' AND dct.title = '🔮 Looking to 2027–2030';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Determine su fase aplicable', 'Compare sus cuentas auditadas del ejercicio 2022 (o su primera declaración de impuestos disponible) con el tramo de facturación actual para confirmar cuándo comienza realmente su obligación.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Determine your applicable phase';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestimmen Sie Ihre anwendbare Phase', 'Vergleichen Sie Ihre geprüften Abschlüsse für das Geschäftsjahr 2022 (oder Ihre erste verfügbare Steuererklärung) mit der aktuellen Umsatzstufe, um zu bestätigen, wann Ihre Pflicht tatsächlich beginnt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Determine your applicable phase';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déterminez votre phase applicable', 'Comparez vos comptes audités de l''exercice 2022 (ou votre première déclaration fiscale disponible) au palier de chiffre d''affaires actuel pour confirmer quand votre obligation débute réellement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Determine your applicable phase';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Regístrese en el portal de desarrolladores de MyInvois', 'Complete la verificación de identidad usando su TIN y BRN (o NRIC para particulares), y solicite acceso a la API — la LHDN emite un ID de cliente y un secreto de cliente para el flujo OAuth 2.0.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Register on the MyInvois developer portal';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie sich im MyInvois-Entwicklerportal', 'Schließen Sie die Identitätsprüfung mit Ihrer TIN und BRN (oder NRIC für Einzelpersonen) ab, und beantragen Sie API-Zugang — die LHDN vergibt eine Client-ID und ein Client-Secret für den OAuth-2.0-Ablauf.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Register on the MyInvois developer portal';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Inscrivez-vous sur le portail développeur MyInvois', 'Complétez la vérification d''identité à l''aide de votre TIN et BRN (ou NRIC pour les particuliers), et demandez l''accès API — la LHDN délivre un identifiant client et un secret client pour le flux OAuth 2.0.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Register on the MyInvois developer portal';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital', 'Obténgalo de una Autoridad de Certificación malasia reconocida — todo documento enviado debe estar firmado digitalmente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Obtain a digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein digitales Zertifikat', 'Beziehen Sie dieses von einer anerkannten malaysischen Zertifizierungsstelle — jedes eingereichte Dokument muss digital signiert sein.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Obtain a digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique', 'Obtenez-le auprès d''une autorité de certification malaisienne reconnue — chaque document soumis doit être signé numériquement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Obtain a digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte sus datos a UBL 2.1', 'Asegúrese de que su ERP o software de facturación pueda generar correctamente los 55 campos obligatorios, en XML o JSON — las fallas de validación se rechazan de forma cerrada, sin aceptación parcial.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Map your data to UBL 2.1';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bilden Sie Ihre Daten auf UBL 2.1 ab', 'Stellen Sie sicher, dass Ihr ERP oder Ihre Rechnungssoftware alle 55 Pflichtfelder korrekt erzeugen kann, in XML oder JSON — Validierungsfehler schlagen fehlgeschlossen zu, ohne Teilakzeptanz.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Map your data to UBL 2.1';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mappez vos données vers UBL 2.1', 'Assurez-vous que votre ERP ou logiciel de facturation peut générer correctement les 55 champs obligatoires, en XML ou JSON — les échecs de validation se soldent par un rejet fermé, sans acceptation partielle.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Map your data to UBL 2.1';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe a fondo en el entorno de sandbox', 'Use sus credenciales de sandbox independientes para validar todo el flujo de envío → validación → sondeo de estado antes de pasar a producción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Test thoroughly in the sandbox environment';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie gründlich in der Sandbox-Umgebung', 'Nutzen Sie Ihre separaten Sandbox-Zugangsdaten, um den vollständigen Ablauf aus Einreichung → Validierung → Statusabfrage zu validieren, bevor Sie zur Produktion wechseln.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Test thoroughly in the sandbox environment';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez minutieusement dans l''environnement bac à sable', 'Utilisez vos identifiants de bac à sable distincts pour valider l''ensemble du flux soumission → validation → interrogation de statut avant de passer en production.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Test thoroughly in the sandbox environment';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Informe a los equipos de ventas y finanzas', 'Ventas debe capturar TINs precisos en la etapa del acuerdo; finanzas necesita una rutina diaria de seguimiento de la cola de rechazos, ya que las correcciones deben producirse rápido dentro de la ventana de 72 horas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Brief sales and finance teams';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Informieren Sie Vertriebs- und Finanzteams', 'Der Vertrieb muss bereits in der Verhandlungsphase korrekte TINs erfassen; das Finanzteam benötigt eine tägliche Routine zur Überwachung der Ablehnungswarteschlange, da Korrekturen innerhalb des 72-Stunden-Fensters schnell erfolgen müssen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Brief sales and finance teams';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Informez les équipes commerciales et financières', 'L''équipe commerciale doit saisir des TIN exacts dès l''étape de la transaction ; la finance a besoin d''une routine quotidienne de suivi de la file des rejets, les corrections devant intervenir rapidement dans la fenêtre de 72 heures.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Brief sales and finance teams';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe la estructura del grupo por exposición como empresa relacionada', 'Confirme si formar parte de un grupo con 1 millón+ RM le incluye en el alcance incluso si su propia facturación individual está por debajo de ese umbral.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Check group structure for related-company exposure';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die Konzernstruktur auf Risiko als verbundenes Unternehmen', 'Bestätigen Sie, ob die Zugehörigkeit zu einer Gruppe mit 1 Million+ RM Sie in den Anwendungsbereich bringt, selbst wenn Ihr eigener Einzelumsatz unter dieser Schwelle liegt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Check group structure for related-company exposure';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez la structure du groupe pour l''exposition en tant qu''entreprise liée', 'Confirmez si le fait d''appartenir à un groupe atteignant 1 million+ RM vous fait entrer dans le champ d''application même si votre propre chiffre d''affaires individuel est inférieur à ce seuil.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Malaysia' AND dst.title = 'Check group structure for related-company exposure';

