INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, outro_text) SELECT dlc.id, 'es', 'Métodos de envío', 'El envío por API se recomienda para volúmenes de facturación moderados a altos — permite la integración directa con el ERP y el procesamiento por lotes automatizado que la entrada manual en el portal no puede igualar.' FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id JOIN deep_dive_lifecycle_card_translations dlct ON dlct.card_id = dlc.id AND dlct.lang = 'en' WHERE co.name_en = 'Malaysia' AND dlct.title = 'Submission methods';
